{item==="why"?"Why Us":item.charAt(0).toUpperCase()+item.slice(1)}
</button>
))}
</div>

<button className="btn btn-primary" onClick={()=>scrollTo("contact")}>Let's Connect <Icon type="arrow" size={17}/></button>
