</div>

<div className="hero-visual">
<div className="mandala"></div>
<img className="hero-image" src="https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=900&q=85" alt="Professional technology team"/>
<div className="hero-badge one">
<div className="badge-icon"><Icon type="spark" size={21}/></div>
<div className="badge-text"><strong>Smart Solutions</strong><span>Built around your goals</span></div>
</div>
<div className="hero-badge two">
